    def rotate(grid, times):
        # Make a deep copy before rotating.
        grid_copy = [row[:] for row in grid]
        for _ in range(times):
            # Rotate 90 degrees clockwise.
            grid_copy = [list(row) for row in zip(*grid_copy[::-1])]
        return grid_copy

