def parking_lot_occupancy(events, capacity):
    occupied = set()  # Tracks currently occupied spot IDs
    for op, spot_id in events:
        if op == "enter":
            if spot_id not in occupied:
                occupied.add(spot_id)
                if len(occupied) > capacity:
                    occupied.remove(spot_id)
        elif op == "exit":
            occupied.discard(spot_id)
    return sorted(occupied)
