        full_cycle = red_a + green_a + yellow_a
        t %= full_cycle
        if t < red_a:
            return 'RED'
        elif t < red_a + green_a:
            return 'GREEN'
        else:
            return 'YELLOW'

    def which_phase_b(t):
        full_cycle = red_b + green_b + yellow_b
        t %= full_cycle
        if t < red_b:
            return 'RED'
        elif t < red_b + green_b:
            return 'GREEN'
        else:
            return 'YELLOW'

