                result.append(grid[0][j])
                border.add((0, j))
        for i in range(1, n):
            if (i, m - 1) not in border:
                result.append(grid[i][m - 1])
                border.add((i, m - 1))
        for j in reversed(range(m - 1)):
            if (n - 1, j) not in border:
                result.append(grid[n - 1][j])
                border.add((n - 1, j))
        for i in reversed(range(n - 1)):
            if (i, 0) not in border:
                result.append(grid[i][0])
                border.add((i, 0))
        if not border:
