def flood_fill(grid, sr, sc, new_val):
    rows = len(grid)
    cols = len(grid[0]) if rows else 0
    if sr < 0 or sr >= rows or sc < 0 or sc >= cols:
        return [row[:] for row in grid]
    original = grid[sr][sc]
    if original == new_val:
        return [row[:] for row in grid]
    to_visit = [(sr, sc)]
    while to_visit:
        r, c = to_visit.pop()
        if grid[r][c] != original:
            continue
        grid[r][c] = new_val
        if r > 0 and grid[r - 1][c] == original:
            to_visit.append((r - 1, c))
        if r < rows - 1 and grid[r + 1][c] == original:
            to_visit.append((r + 1, c))
        if c > 0 and grid[r][c - 1] == original:
            to_visit.append((r, c - 1))
        if c < cols - 1 and grid[r][c + 1] == original:
            to_visit.append((r, c + 1))
    return [row[:] for row in grid]
```

